1	//! MPSC v1 ring: the v0 ring with the seq values of spsc v1,
2	//! so `capacity` runs down to 1, per the design doc's "MPSC v1:
3	//! equality-seq ring" section. A sibling of v0 under the same
4	//! module layout, so the two measure side by side:
5	//!
6	//! - Same region shape as the SPSC ring — a four-line
7	//!   [`MpscHeader`] then slots — plus a per-slot sequence
8	//!   array between them: `seq[pos]` publishes each slot
9	//!   independently, because claim order and commit order
10	//!   differ under concurrent producers.
11	//! - Producers CAS-claim `producer_idx`; the consumer stays
12	//!   CAS-free. Fullness is read from the slot seq, so
13	//!   producers never load `consumer_idx`.
14	//! - `capacity` may be any power of two down to 1, the change
15	//!   from v0: a slot is claimable at `seq == pos`, committed at
16	//!   `pos + M + 1`, released at `pos + M`, checked by equality.
17	//!   v0's Vyukov `pos + 1` for committed equals released at
18	//!   `M = 1` and wedges both sides there.
19	//! - Own magic and layout version: a region is one kind or
20	//!   the other, and cross-attaching fails toward
21	//!   [`Error::BadMagic`].
22	//! - The claim CAS raises the atomic floor for MPSC users
23	//!   only — this module is gated on `target_has_atomic =
24	//!   "32"`; the SPSC ring stays load/store-only.
25	
26	use core::marker::PhantomData;
27	use core::mem::size_of;
28	use core::sync::atomic::{AtomicU32, Ordering};
29	
30	use crate::{CACHE_LINE_SIZE, CacheAligned, Error, USER_WORDS};
31	
32	mod consumer;
33	mod producer;
34	
35	pub use consumer::{MpscConsumer, MpscReadSlot};
36	pub use producer::MpscProducer;
37	
38	/// Layout marker written by [`MpscRing::init`]; distinct from
39	/// the SPSC and MPSC v0 magics so a cross-kind or cross-version
40	/// attach fails toward [`Error::BadMagic`]: a v0 region carries
41	/// v0's seq values, which this ring would misread.
42	const MPSC_MAGIC: u32 = 0x5A43_4D32; // "ZCM2"
43	
44	/// Bumped on any change to the MPSC v1 region layout;
45	/// independent of the v0 and SPSC layout versions.
46	const MPSC_LAYOUT_VERSION: u32 = 1;
47	
48	/// Capacity bound: `2^30`, not the SPSC `2^31` — the seq
49	/// tombstone encoding reserves index-arithmetic headroom (see
50	/// the design doc's "MPSC open questions").
51	const MPSC_MAX_CAPACITY: u32 = 1 << 30;
52	
53	/// Tombstone offset: an unwound `send_with` commits
54	/// `pos + M + 1 + TOMBSTONE` instead of `pos + M + 1`, marking
55	/// a claimed slot the consumer must release without
56	/// delivering.
57	///
58	/// - Unambiguous at both wait points: the consumer at `c`
59	///   legitimately sees only `c` (not yet committed),
60	///   `c + M + 1` (committed), or that plus `2^31` (tombstone),
61	///   distinct while `M <= 2^30`; a producer reads a tombstoned
62	///   previous lap as anything but `pos`, so "full", until the
63	///   consumer skips it, which is the correct backpressure.
64	pub(crate) const TOMBSTONE: u32 = 1 << 31;
65	
66	/// Control block at offset 0 of an MPSC region — same
67	/// four-line shape as the SPSC [`Header`](crate::spsc::v0::Header), but
68	/// its own type: the layouts evolve independently and the
69	/// index-ownership story differs.
70	///
71	/// - line 0: geometry, written by [`MpscRing::init`] with
72	///   `magic` last (`Release`), read-only thereafter.
73	/// - line 1: `producer_idx` — CAS-claimed by *all* producers
74	///   (the contended line), never read by the consumer's hot
75	///   path.
76	/// - line 2: `consumer_idx` — written only by the consumer;
77	///   never read by producers (fullness comes from the slot
78	///   seq), so it is resume state and diagnostic occupancy.
79	/// - line 3: `user`, app-owned scratch — same contract as the
80	///   SPSC user line.
81	/// - Every field is atomic: the region may be mapped by a
82	///   peer at any time.
83	#[repr(C)]
84	pub struct MpscHeader {
85	    /// Layout marker ([`MPSC_MAGIC`]); stored last by init
86	    /// (`Release`), loaded first by attach (`Acquire`).
87	    magic: AtomicU32,
88	    /// Layout version ([`MPSC_LAYOUT_VERSION`]).
89	    layout_version: AtomicU32,
90	    /// Slot size N in bytes — a [`CACHE_LINE_SIZE`] multiple.
91	    slot_size: AtomicU32,
92	    /// Slot count M — a power of two `<= 2^30`.
93	    capacity: AtomicU32,
94	    /// [`CACHE_LINE_SIZE`] this region was built with.
95	    cache_line_size: AtomicU32,
96	    /// Free-running count of slot positions claimed by
97	    /// producers (CAS).
98	    producer_idx: CacheAligned<AtomicU32>,
99	    /// Free-running count of messages released; consumer-owned
100	    /// resume state, not read by producers.
101	    consumer_idx: CacheAligned<AtomicU32>,
102	    /// App-owned scratch line ([`USER_WORDS`] words): zeroed by
103	    /// init, then never touched by the crate.
104	    user: CacheAligned<[AtomicU32; USER_WORDS]>,
105	}
106	
107	const _: () = assert!(size_of::<MpscHeader>() == 4 * CACHE_LINE_SIZE);
108	
109	/// A validated view over an MPSC ring region.
110	///
111	/// - Geometry is snapshotted out of the header at init/attach,
112	///   as the SPSC ring does: per-op paths never re-read fields
113	///   a peer could scribble on.
114	/// - Region layout: [`MpscHeader`], the seq array (`M ×
115	///   AtomicU32`, padded up to a cache line), then M slots of N
116	///   bytes.
117	pub struct MpscRing<'a> {
118	    /// The region's control block.
119	    header: &'a MpscHeader,
120	    /// Base of the per-slot sequence array.
121	    seqs: *const AtomicU32,
122	    /// Base of the slot array.
123	    slots: *mut u8,
124	    /// Snapshot of `header.slot_size`.
125	    slot_size: u32,
126	    /// Snapshot of `header.capacity`.
127	    capacity: u32,
128	    /// Slot-position mask (`capacity - 1`).
129	    mask: u32,
130	    _region: PhantomData<&'a [u8]>,
131	}
132	
133	impl<'a> MpscRing<'a> {
134	    /// Initialize a fresh region and return the ring over it.
135	    ///
136	    /// - `slot_size` — N bytes per slot, a [`CACHE_LINE_SIZE`]
137	    ///   multiple.
138	    /// - `capacity` — M slots, a power of two from 1 to `2^30`.
139	    /// - The region must be [`CACHE_LINE_SIZE`]-aligned and at
140	    ///   least [`mpsc_region_size`] bytes.
141	    pub fn init(region: &'a mut [u8], slot_size: u32, capacity: u32) -> Result<Self, Error> {
142	        validate_mpsc_geometry(slot_size, capacity)?;
143	        let len = region.len();
144	        // Taken exactly once — see `Ring::init` for the Stacked
145	        // Borrows rationale.
146	        let base = region.as_mut_ptr();
147	        let header = mpsc_header_ptr(base, len)?;
148	        if (len as u64) < mpsc_region_size(slot_size, capacity) {
149	            return Err(Error::TooSmall);
150	        }
151	        // SAFETY: alignment + room for the MpscHeader checked
152	        // by mpsc_header_ptr; region is exclusively borrowed
153	        // for 'a; any byte pattern is a valid MpscHeader
154	        // (all-atomic fields, plain-byte padding).
155	        let header = unsafe { &*header };
156	        header
157	            .layout_version
158	            .store(MPSC_LAYOUT_VERSION, Ordering::Relaxed);
159	        header.slot_size.store(slot_size, Ordering::Relaxed);
160	        header.capacity.store(capacity, Ordering::Relaxed);
161	        header
162	            .cache_line_size
163	            .store(CACHE_LINE_SIZE as u32, Ordering::Relaxed);
164	        header.producer_idx.store(0, Ordering::Relaxed);
165	        header.consumer_idx.store(0, Ordering::Relaxed);
166	        for word in header.user.iter() {
167	            word.store(0, Ordering::Relaxed);
168	        }
169	        // SAFETY: in bounds — len covers header + seq array.
170	        let seqs = unsafe { base.add(size_of::<MpscHeader>()) } as *const AtomicU32;
171	        // seq[i] = i marks every slot claimable by the position
172	        // that will first reach it.
173	        for i in 0..capacity {
174	            // SAFETY: i < capacity, inside the seq array
175	            // validated by the region-size check.
176	            unsafe { &*seqs.add(i as usize) }.store(i, Ordering::Relaxed);
177	        }
178	        // Published last: a peer that pre-mapped the region must
179	        // never observe the magic before the geometry and seq
180	        // stores it validates and relies on.
181	        header.magic.store(MPSC_MAGIC, Ordering::Release);
182	        // SAFETY: in bounds — len covers header + seqs + slots.
183	        let slots = unsafe { base.add(slots_offset(capacity)) };
184	        Ok(MpscRing {
185	            header,
186	            seqs,
187	            slots,
188	            slot_size,
189	            capacity,
190	            mask: capacity - 1,
191	            _region: PhantomData,
192	        })
193	    }
194	
195	    /// Attach to a region another process (or an earlier call)
196	    /// already initialized, validating its header.
197	    ///
198	    /// # Safety
199	    ///
200	    /// - `region` points to `len` bytes of memory that outlive
201	    ///   `'a`, genuinely shared and writable (e.g. a
202	    ///   `MAP_SHARED` mapping).
203	    /// - At most one consumer attaches; any number of
204	    ///   producers may (MPSC contract).
205	    pub unsafe fn attach(region: *mut u8, len: usize) -> Result<Self, Error> {
206	        let header = mpsc_header_ptr(region, len)?;
207	        // SAFETY: alignment + room for the MpscHeader checked
208	        // by mpsc_header_ptr; caller guarantees the memory is
209	        // live and shared.
210	        let header = unsafe { &*header };
211	        // Acquire pairs with init's Release store of magic: a
212	        // valid magic means the geometry and seq stores are
213	        // visible.
214	        if header.magic.load(Ordering::Acquire) != MPSC_MAGIC {
215	            return Err(Error::BadMagic);
216	        }
217	        if header.layout_version.load(Ordering::Relaxed) != MPSC_LAYOUT_VERSION {
218	            return Err(Error::BadLayoutVersion);
219	        }
220	        if header.cache_line_size.load(Ordering::Relaxed) != CACHE_LINE_SIZE as u32 {
221	            return Err(Error::BadCacheLine);
222	        }
223	        // Snapshot geometry once; per-op paths never re-read it.
224	        let slot_size = header.slot_size.load(Ordering::Relaxed);
225	        let capacity = header.capacity.load(Ordering::Relaxed);
226	        validate_mpsc_geometry(slot_size, capacity)?;
227	        if (len as u64) < mpsc_region_size(slot_size, capacity) {
228	            return Err(Error::TooSmall);
229	        }
230	        // SAFETY: in bounds — len covers header + seqs + slots.
231	        let seqs = unsafe { region.add(size_of::<MpscHeader>()) } as *const AtomicU32;
232	        // SAFETY: as above.
233	        let slots = unsafe { region.add(slots_offset(capacity)) };
234	        Ok(MpscRing {
235	            header,
236	            seqs,
237	            slots,
238	            slot_size,
239	            capacity,
240	            mask: capacity - 1,
241	            _region: PhantomData,
242	        })
243	    }
244	
245	    /// Split into one producer handle and the consumer handle.
246	    ///
247	    /// - The producer is `Clone`: one clone per producing
248	    ///   thread (MPSC contract). The consumer is unique per
249	    ///   process; cross-process, exactly one consuming process
250	    ///   is the caller's contract (see [`MpscRing::attach`]).
251	    pub fn split(self) -> (MpscProducer<'a>, MpscConsumer<'a>) {
252	        (
253	            MpscProducer::new(
254	                self.header,
255	                self.seqs,
256	                self.slots,
257	                self.slot_size,
258	                self.capacity,
259	                self.mask,
260	            ),
261	            MpscConsumer::new(
262	                self.header,
263	                self.seqs,
264	                self.slots,
265	                self.slot_size,
266	                self.capacity,
267	                self.mask,
268	            ),
269	        )
270	    }
271	}
272	
273	/// Validate a region base pointer and cast it to the
274	/// [`MpscHeader`] it must start with; shared by init / attach.
275	///
276	/// - Same split of duties as the SPSC `header_ptr`: alignment
277	///   and header room here, full-geometry length with the
278	///   caller.
279	fn mpsc_header_ptr(base: *mut u8, len: usize) -> Result<*const MpscHeader, Error> {
280	    if !(base as usize).is_multiple_of(CACHE_LINE_SIZE) {
281	        return Err(Error::Misaligned);
282	    }
283	    if len < size_of::<MpscHeader>() {
284	        return Err(Error::TooSmall);
285	    }
286	    Ok(base as *const MpscHeader)
287	}
288	
289	/// Bytes the seq array occupies, padded up to a cache line so
290	/// the slot array behind it stays line-aligned.
291	///
292	/// - u64: `capacity * 4` reaches `2^32` at the `2^30` cap,
293	///   which would wrap a 32-bit usize.
294	fn seq_bytes(capacity: u32) -> u64 {
295	    (capacity as u64 * size_of::<AtomicU32>() as u64).next_multiple_of(CACHE_LINE_SIZE as u64)
296	}
297	
298	/// Byte offset of the slot array: header, then the padded seq
299	/// array.
300	///
301	/// - usize return: callers offset a pointer with it, and only
302	///   after the u64 region-size check has proven the region —
303	///   hence this offset — fits in memory.
304	fn slots_offset(capacity: u32) -> usize {
305	    size_of::<MpscHeader>() + seq_bytes(capacity) as usize
306	}
307	
308	/// Bytes needed for an MPSC region with the given geometry.
309	///
310	/// - Computed in u64 for the same 32-bit wrap reason as the
311	///   SPSC `region_size`.
312	pub fn mpsc_region_size(slot_size: u32, capacity: u32) -> u64 {
313	    size_of::<MpscHeader>() as u64 + seq_bytes(capacity) + slot_size as u64 * capacity as u64
314	}
315	
316	/// Geometry checks for [`MpscRing::init`] / [`MpscRing::attach`].
317	///
318	/// - Slot size as the SPSC ring; capacity additionally capped
319	///   at [`MPSC_MAX_CAPACITY`] for tombstone headroom.
320	fn validate_mpsc_geometry(slot_size: u32, capacity: u32) -> Result<(), Error> {
321	    if slot_size == 0 || !(slot_size as usize).is_multiple_of(CACHE_LINE_SIZE) {
322	        return Err(Error::BadSlotSize);
323	    }
324	    if capacity == 0 || !capacity.is_power_of_two() || capacity > MPSC_MAX_CAPACITY {
325	        return Err(Error::BadCapacity);
326	    }
327	    Ok(())
328	}
