335	    /// Test region: header + seq line (4 × 4 B padded to 64) +
336	    /// 4 slots × 1 line.
337	    const REGION_BYTES: usize = size_of::<MpscHeader>() + CACHE_LINE_SIZE + (4 * CACHE_LINE_SIZE);
338	
339	    /// Cache-line-aligned backing store for the tests' rings.
340	    #[repr(C, align(64))]
341	    struct Region([u8; REGION_BYTES]);
342	
343	    impl Region {
344	        fn new() -> Self {
345	            Region([0; REGION_BYTES])
346	        }
347	    }
