349	    #[test]
350	    fn mpsc_region_size_accounts_for_seq_array() {
351	        // 4 slots: header 256 + seq 16→64 + slots 256 = 576.
352	        assert_eq!(mpsc_region_size(64, 4), 576);
353	        // 32 slots: seq 128 is already a line multiple.
354	        assert_eq!(
355	            mpsc_region_size(64, 32),
356	            (size_of::<MpscHeader>() + 128 + 32 * 64) as u64
357	        );
358	    }
