360	    #[test]
361	    fn mpsc_init_rejects_bad_geometry() {
362	        let mut r = Region::new();
363	        assert_eq!(
364	            MpscRing::init(&mut r.0, 63, 4).err().unwrap(),
365	            Error::BadSlotSize
366	        );
367	        assert_eq!(
368	            MpscRing::init(&mut r.0, 0, 4).err().unwrap(),
369	            Error::BadSlotSize
370	        );
371	        assert_eq!(
372	            MpscRing::init(&mut r.0, 64, 3).err().unwrap(),
373	            Error::BadCapacity
374	        );
375	        assert_eq!(
376	            MpscRing::init(&mut r.0, 64, 0).err().unwrap(),
377	            Error::BadCapacity
378	        );
379	        // Over the MPSC cap (fine for SPSC): tombstone headroom.
380	        assert_eq!(
381	            MpscRing::init(&mut r.0, 64, 1 << 31).err().unwrap(),
382	            Error::BadCapacity
383	        );
384	        assert_eq!(
385	            MpscRing::init(&mut r.0, 64, 8).err().unwrap(),
386	            Error::TooSmall
387	        );
388	        assert_eq!(
389	            MpscRing::init(&mut r.0[1..], 64, 4).err().unwrap(),
390	            Error::Misaligned
391	        );
392	        // 32-bit tripwire, as the SPSC test: N * M wraps a
393	        // 32-bit usize; the u64 region size must still reject.
394	        assert_eq!(
395	            MpscRing::init(&mut r.0, 1 << 26, 1 << 6).err().unwrap(),
396	            Error::TooSmall
397	        );
398	        // An SPSC-sized region (no seq line) is too small here.
399	        let spsc_bytes = size_of::<Header>() + 4 * 64;
400	        assert_eq!(
401	            MpscRing::init(&mut r.0[..spsc_bytes], 64, 4).err().unwrap(),
402	            Error::TooSmall
403	        );
404	    }
