406	    #[test]
407	    fn mpsc_init_seeds_seq_array() {
408	        let mut r = Region::new();
409	        // Dirty the region so the seq stores are observable.
410	        r.0.fill(0xAA);
411	        let ring = MpscRing::init(&mut r.0, 64, 4).unwrap();
412	        for i in 0..4 {
413	            // SAFETY: i < capacity; test mirrors init's bounds.
414	            let seq = unsafe { &*ring.seqs.add(i as usize) };
415	            assert_eq!(seq.load(Ordering::Relaxed), i);
416	        }
417	        assert_eq!(ring.slot_size, 64);
418	        assert_eq!(ring.capacity, 4);
419	        assert_eq!(ring.mask, 3);
420	    }
