422	    #[test]
423	    fn mpsc_attach_validates_header() {
424	        let mut r = Region::new();
425	        // Not initialized yet: magic is zero.
426	        let err = unsafe { MpscRing::attach(r.0.as_mut_ptr(), r.0.len()) }
427	            .err()
428	            .unwrap();
