478	    use crate::{Empty, Full};
479	    use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};
480	
481	    /// Test message; two words so a torn write would be
482	    /// visible, `val` doubles as the producer id in threaded
483	    /// tests.
484	    #[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Debug, PartialEq)]
485	    #[repr(C)]
486	    struct Msg {
487	        seq: u64,
488	        val: u64,
489	    }
