491	    #[test]
492	    fn mpsc_roundtrip_full_empty() {
493	        let mut r = Region::new();
494	        let (prod, mut cons) = MpscRing::init(&mut r.0, 64, 4).unwrap().split();
495	
496	        // Empty at start.
497	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
498	
499	        // Fill all 4 slots, then Full on a single probe.
500	        for i in 0..4u64 {
501	            prod.send_with::<Msg>(
502	                |_| false,
503	                |m| {
504	                    m.seq = i;
505	                    m.val = i * 10;
506	                },
507	            )
508	            .unwrap();
509	        }
510	        assert_eq!(
511	            prod.send_with::<Msg>(|_| false, |_| {}).err().unwrap(),
512	            Full
513	        );
514	
515	        // Drain in order; then empty again.
516	        for i in 0..4u64 {
517	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
518	            assert_eq!(
519	                *msg,
520	                Msg {
521	                    seq: i,
522	                    val: i * 10
523	                }
524	            );
525	            msg.release();
526	        }
527	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
528	
529	        // One more send lands in the masked-around slot 0.
530	        prod.send_with::<Msg>(
531	            |_| false,
532	            |m| {
533	                m.seq = 4;
534	                m.val = 0;
535	            },
536	        )
537	        .unwrap();
538	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
539	        assert_eq!(msg.seq, 4);
540	        msg.release();
541	    }
