543	    #[test]
544	    fn mpsc_policies_count_and_give_up() {
545	        let mut r = Region::new();
546	        let (prod, mut cons) = MpscRing::init(&mut r.0, 64, 4).unwrap().split();
547	
548	        // Empty ring: the consumer's policy sees 0-based
549	        // attempts and its `false` becomes Err(Empty).
550	        let mut seen = Vec::new();
551	        let err = cons
552	            .reserve_slot_with::<Msg>(|attempt| {
553	                seen.push(attempt);
554	                attempt < 2
555	            })
556	            .err()
557	            .unwrap();
558	        assert_eq!(err, Empty);
559	        assert_eq!(seen, [0, 1, 2]);
560	
561	        // Fill the ring: the producer's policy gives up with
562	        // Err(Full), and the failed send has zero footprint —
563	        // the fill closure never ran.
564	        for i in 0..4u64 {
565	            prod.send_with::<Msg>(|_| false, |m| m.seq = i).unwrap();
566	        }
567	        let mut seen = Vec::new();
568	        let err = prod
569	            .send_with::<Msg>(
570	                |attempt| {
571	                    seen.push(attempt);
572	                    attempt < 2
573	                },
574	                |_| panic!("fill ran on a full ring"),
575	            )
576	            .err()
577	            .unwrap();
578	        assert_eq!(err, Full);
579	        assert_eq!(seen, [0, 1, 2]);
580	
581	        // With room / messages available the policy is never
582	        // consulted.
583	        let msg = cons
584	            .reserve_slot_with::<Msg>(|_| panic!("policy consulted with a message available"))
585	            .unwrap();
586	        assert_eq!(msg.seq, 0);
587	        msg.release();
588	        prod.send_with::<Msg>(
589	            |_| panic!("policy consulted with room available"),
590	            |m| m.seq = 4,
591	        )
592	        .unwrap();
593	    }
