771	    /// Two producers over `capacity` slots: per-producer FIFO
772	    /// holds and nothing is lost.
773	    fn two_producers(capacity: u32) {
774	        // Reduced under Miri: interpreted spin loops are slow.
775	        const COUNT: u64 = if cfg!(miri) { 100 } else { 50_000 };
776	        const PRODUCERS: u64 = 2;
777	        let mut r = Region::new();
778	        let (prod, mut cons) = MpscRing::init(&mut r.0, 64, capacity).unwrap().split();
779	
780	        std::thread::scope(|s| {
781	            for p in 0..PRODUCERS {
782	                let prod = prod.clone();
783	                s.spawn(move || {
784	                    for i in 0..COUNT {
785	                        prod.send_with::<Msg>(crate::policy::spin, |m| {
786	                            m.seq = i;
787	                            m.val = p;
788	                        })
789	                        .unwrap(); // OK: policy::spin never gives up
790	                    }
791	                });
792	            }
793	            s.spawn(move || {
794	                // Global arrival order is claim order; only
795	                // per-producer FIFO is promised.
796	                let mut next = [0u64; PRODUCERS as usize];
797	                for _ in 0..PRODUCERS * COUNT {
798	                    let msg = cons.reserve_slot_with::<Msg>(crate::policy::spin).unwrap(); // OK: policy::spin never gives up
799	                    let p = msg.val as usize;
800	                    assert_eq!(msg.seq, next[p], "per-producer order broken");
801	                    next[p] += 1;
802	                    msg.release();
803	                }
804	                assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
805	            });
806	        });
807	    }
